import{_ as a,o as t,c as o,a2 as r}from"./chunks/framework.CT6jiXWi.js";const u=JSON.parse('{"title":"CDS 10, HCQL and MCP","description":"","frontmatter":{},"headers":[],"relativePath":"concepts/cds-10.md","filePath":"concepts/cds-10.md","lastUpdated":1783592518000}'),n={name:"concepts/cds-10.md"};function s(d,e,c,i,l,p){return t(),o("div",null,[...e[0]||(e[0]=[r(`<h1 id="cds-10-hcql-and-mcp" tabindex="-1">CDS 10, HCQL and MCP <a class="header-anchor" href="#cds-10-hcql-and-mcp" aria-label="Permalink to &quot;CDS 10, HCQL and MCP&quot;">​</a></h1><p>CAP&#39;s June 2026 release (<strong>cds 10</strong>) adds two capabilities that compose with <code>cds-data</code> <strong>without any change to your annotations or pipeline configuration</strong>. Both build on the same fact: queries reach the plugins only when dispatched through the application service.</p><p>All three <code>cds-data</code> packages run on both CDS 9 and CDS 10 (<code>@sap/cds &gt;= 9</code>). The behavior below only activates on CDS 10 with a CAP-to-CAP hop or the MCP adapter installed.</p><h2 id="hcql-—-a-faster-wire-protocol-for-delegate-and-replicate" tabindex="-1">HCQL — a faster wire protocol for delegate and replicate <a class="header-anchor" href="#hcql-—-a-faster-wire-protocol-for-delegate-and-replicate" aria-label="Permalink to &quot;HCQL — a faster wire protocol for delegate and replicate&quot;">​</a></h2><p><strong>HCQL</strong> (CQL over HTTP) is a new CAP protocol adapter that carries a CQN <code>SELECT</code> as an HTTP request instead of translating it to OData <code>$filter</code> / <code>$select</code>. For <strong>CAP-to-CAP</strong> integration, CAP&#39;s remote client <strong>auto-selects HCQL</strong> over OData when the provider serves <code>@hcql</code>. CAP describes HCQL as <em>&quot;best suited, and thus chosen automatically for data federation scenarios.&quot;</em></p><p>The plugins never serialize the wire protocol themselves — they forward CQN via <code>remote.run(query)</code>. So both federation strategies benefit transparently:</p><table tabindex="0"><thead><tr><th>Strategy</th><th>Read path</th><th>HCQL benefit</th></tr></thead><tbody><tr><td><code>@federation.delegate</code></td><td><code>remote.run(req.query)</code> on the application service</td><td>Richer path expressions (flattened associations like <code>customer.name</code>) that OData-only remotes cannot express</td></tr><tr><td><code>@federation.replicate</code></td><td>Pipeline READ phase via the engine&#39;s remote adapter</td><td>Same adapter handles OData V2/V4 and HCQL; delta paging is unchanged</td></tr></tbody></table><p>There is <strong>no <code>@federation.hcql</code> strategy</strong> and no adapter to pick — HCQL is a CAP-runtime choice. Annotate the CAP provider <code>@hcql @odata</code> and bind the consumer as usual. See:</p><ul><li><a href="/cds-data/federation/concepts/service-query-execution.html#cds-10-hcql-and-mcp">Federation → Service query execution</a> — the dispatch story.</li><li><a href="/cds-data/pipeline/guide/sources/odata.html">Pipeline → Remote CQN sources (OData &amp; HCQL)</a> — adapter details and flattened-column behavior.</li></ul><h2 id="mcp-—-exposing-data-to-ai-agents" tabindex="-1">MCP — exposing data to AI agents <a class="header-anchor" href="#mcp-—-exposing-data-to-ai-agents" aria-label="Permalink to &quot;MCP — exposing data to AI agents&quot;">​</a></h2><p>CAP&#39;s <a href="https://cap.cloud.sap/docs/guides/protocols/mcp" target="_blank" rel="noreferrer"><code>@cap-js/mcp</code></a> protocol adapter exposes a service to AI agents over the <strong>Model Context Protocol</strong>. Annotate a service <code>@mcp: &#39;agent&#39;</code> and its entities become MCP tools (<code>describe</code>, <code>query</code>, <code>call_action</code>).</p><p>Because MCP <code>query</code> calls run <strong>CQN on the application service</strong>, they hit the same <code>@federation.delegate</code> / <code>@federation.replicate</code> handlers that OData and <code>srv.run</code> do — MCP never calls remote providers directly:</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>AI agent ──tools/call query──▶ @mcp service ──srv.run(CQN)──▶ federation handler</span></span>
<span class="line"><span>                                                              ├─ delegate → remote provider</span></span>
<span class="line"><span>                                                              └─ replicate → local synced table</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>An MCP agent transparently gets live-proxied remote data (delegate), locally synced data (replicate), or cached responses — with no MCP-specific federation code. See <a href="/cds-data/federation/integration/mcp.html">Federation → MCP integration</a> for a runnable demo.</p>`,14)])])}const g=a(n,[["render",s]]);export{u as __pageData,g as default};
